#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1'000'000'007LL;

struct Effect {
    long long a, b;
};

long long modPow(long long a, long long e) {
    long long result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return result;
}

long long applyRepeated(long long value, long long a, long long b, long long count) {
    long long resultA = 1, resultB = 0;
    long long baseA = a % MOD, baseB = b % MOD;

    while (count > 0) {
        if (count & 1) {
            resultB = (baseA * resultB + baseB) % MOD;
            resultA = baseA * resultA % MOD;
        }
        baseB = (baseA * baseB + baseB) % MOD;
        baseA = baseA * baseA % MOD;
        count >>= 1;
    }
    return (resultA * value + resultB) % MOD;
}

long long ceilDiv(long long numerator, long long denominator) {
    long long q = numerator / denominator;
    long long r = numerator % denominator;
    if (r > 0) ++q;
    return q;
}

