        if (x.a != y.a) return x.a < y.a;
        return x.b > y.b;
    });

    vector<Effect> uniqueSpells;
    for (const auto &e : spells) {
        if (!uniqueSpells.empty() && uniqueSpells.back().a == e.a) continue;
        uniqueSpells.push_back(e);
    }

    vector<Effect> hull;
    vector<long long> start;
    for (const auto &e : uniqueSpells) {
        long long s = LLONG_MIN;
