        __int128 lhs = (__int128)x.b * yDen;
        __int128 rhs = (__int128)y.b * xDen;
        return lhs > rhs;
    });

    long long mealMul = 1, mealAdd = 0;
    for (const auto &e : meals) {
        mealMul = mealMul * (e.a % MOD) % MOD;
        mealAdd = (e.a % MOD * mealAdd + e.b) % MOD;
    }

