    cin >> Q;
    while (Q--) {
        long long x;
        cin >> x;

        long long y = x;
        long long yMod = x % MOD;
        long long remaining = K;

        while (remaining > 0) {
            int idx = int(upper_bound(start.begin(), start.end(), y) - start.begin()) - 1;
            if (idx == (int)hull.size() - 1) {
                yMod = applyRepeated(yMod, hull[idx].a, hull[idx].b, remaining);
                remaining = 0;
                break;
            }

            const auto &e = hull[idx];
            long long threshold = start[idx + 1];

            if (e.a == 1) {
                long long needed = (threshold - y + e.b - 1) / e.b;
                long long steps = min(remaining, needed);
                y += steps * e.b;
                yMod = (yMod + (steps % MOD) * (e.b % MOD)) % MOD;
                remaining -= steps;
