                y = (long long)((__int128)e.a * y + e.b);
                yMod = (e.a % MOD * yMod + e.b) % MOD;
                --remaining;
            }
        }

        long long answer = (mealMul * yMod + mealAdd) % MOD;
        cout << answer << '\n';
    }

    return 0;
